  await page.waitForTimeout(1000);

  const measure = async (label) => page.evaluate((label) => {
    const header = document.querySelector('header');
    const params = document.getElementById('paramsBar');
    const form = document.querySelector('.upload-form');
    const chips = [...params.children];
    const tops = [...new Set(chips.map(c => Math.round(c.getBoundingClientRect().top)))].sort((a,b)=>a-b);
    return {
      label,
      headerH: header.getBoundingClientRect().height,
