      chipWidths: chips.map(c => Math.round(c.getBoundingClientRect().width)),
    };
  }, label);

  // Force preview (ellipsis) state via internal API if exposed; otherwise recreate DOM
  // viewer.js is an IIFE - not exposed. Simulate by temporarily setting innerHTML like preview.
  const previewHTML = await page.evaluate(() => {
    // Capture current filled HTML
    return document.getElementById('paramsBar').innerHTML;
  });

  // Build preview-like chips: keep metrics loading + use ellipsis for secondary by cloning structure
  await page.evaluate(() => {
    // Re-trigger loading preview by dispatching through visible UI path:
