    if (window.MathJax) await MathJax.typesetPromise([document.getElementById('paramsBar')]);
  });
  await page.waitForTimeout(300);
  console.log(JSON.stringify(await measure('PREVIEW'), null, 2));

  // Restore filled
  await page.evaluate((html) => { document.getElementById('paramsBar').innerHTML = html; }, previewHTML);
  await page.evaluate(async () => {
    if (window.MathJax) await MathJax.typesetPromise([document.getElementById('paramsBar')]);
  });
