      const fmt = (v) => { const n = parseFloat(v); return Math.abs(n) >= 1000 ? n.toFixed(1) : n.toFixed(4); };
      const metric = (label, kind) => `<span class="params-metric params-metric--blue params-metric--${kind}"><span class="params-metric-body"><span class="params-metric-label">${label}</span><span class="params-metric-value params-metric-value--loading"><span class="button-spinner params-spinner"></span></span></span></span>`;
      document.getElementById('paramsBar').innerHTML = `
