        <span>|stream| <b>…</b></span>
        <span style="color:var(--text-dim)">|simplified| <b>…</b></span>
        <span style="color:var(--text-dim)">ratio <b>…</b></span>`;
    });
    await page.evaluate(async () => { if (window.MathJax) await MathJax.typesetPromise([document.getElementById('paramsBar')]); });
    await page.waitForTimeout(150);
    const p = await measure(`PREVIEW@${w}`);
    await page.evaluate((html) => { document.getElementById('paramsBar').innerHTML = html; }, previewHTML);
    await page.evaluate(async () => { if (window.MathJax) await MathJax.typesetPromise([document.getElementById('paramsBar')]); });
    await page.waitForTimeout(150);
    const f = await measure(`FILLED@${w}`);
    console.log(JSON.stringify({ w, previewH: p.headerH, filledH: f.headerH, previewRows: p.rowCount, filledRows: f.rowCount, previewParamsH: p.paramsH, filledParamsH: f.paramsH }, null, 2));
  }

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
