node <<'JS'
const { chromium } = require('/tmp/node_modules/playwright');
const path = require('path');
const out = '/Users/sinchunyeung/github/simplification-of-trajectory-streams/web/usability';
(async () => {
  const browser = await chromium.launch({ headless: true });

  const fixture = await browser.newPage({ viewport: { width: 780, height: 1200 } });
  await fixture.goto('file://' + path.join(out, 'desktop-721-params-wrap.html'));
  await fixture.screenshot({ path: path.join(out, 'desktop-721-params-wrap.png'), fullPage: true });
  console.log('fixture ok');
  await fixture.close();

  const page = await browser.newPage({ viewport: { width: 721, height: 900 } });
  await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'networkidle' });

  let releaseGate;
  const gate = new Promise(r => { releaseGate = r; });
  await page.route(/\/api\//, async (route) => {
    await gate;
    await route.continue();
  });
  await page.selectOption('#traceSelect', '1');
  page.click('#loadBtn');
  await page.waitForFunction(() => {
    const p = document.getElementById('paramsBar');
    return p && p.children.length >= 5 && getComputedStyle(p).minHeight === '76px';
  }, { timeout: 15000 });
  await page.waitForTimeout(300);
  await page.locator('header').screenshot({ path: path.join(out, 'desktop-721-params-wrap-live.png') });
  const loading = await page.evaluate(() => document.querySelector('header').getBoundingClientRect().height);
  console.log('loading header', loading);
  releaseGate();
  await page.waitForFunction(() => (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'), { timeout: 180000 });
  await page.waitForTimeout(600);
  await page.locator('header').screenshot({ path: path.join(out, 'desktop-721-params-wrap-loaded-live.png') });
  const loaded = await page.evaluate(() => document.querySelector('header').getBoundingClientRect().height);
  console.log('loaded header', loaded);

  // 900 / 1280 / 390 regressions with real loaded state
  for (const [w,h,name] of [[900,900,'900'],[1280,900,'1280'],[390,800,'390']]) {
    await page.setViewportSize({ width: w, height: h });
    await page.waitForTimeout(200);
    await page.locator('header').screenshot({ path: path.join(out, `desktop-721-params-wrap-${name}-regression-live.png`) });
    const m = await page.evaluate(() => ({
      headerH: document.querySelector('header').getBoundingClientRect().height,
      paramsH: document.getElementById('paramsBar').getBoundingClientRect().height,
      minH: getComputedStyle(document.getElementById('paramsBar')).minHeight,
    }));
    console.log('reg', name, m);
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
